const config = {
  "previewFeatures": [],
  "clientVersion": "7.3.0",
  "engineVersion": "9d6ad21cbbceab97458517b147a6a09ff43aa735",
  "activeProvider": "postgresql",
  "inlineSchema": "// Prisma schema for Drug Management System\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"./generated/client\"\n  binaryTargets = [\"native\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// Users: Admin (Sở Y tế) và Facility (Cơ sở)\nmodel User {\n  id           String  @id @default(cuid())\n  username     String  @unique\n  passwordHash String  @map(\"password_hash\")\n  role         Role    @default(FACILITY)\n  facilityName String? @map(\"facility_name\")\n  facilityCode String? @unique @map(\"facility_code\")\n  isActive     Boolean @default(true) @map(\"is_active\")\n\n  // Thông tin thêm cho cơ sở\n  autonomyGroup String? @map(\"autonomy_group\")\n  facilityType  String? @map(\"facility_type\")\n  contactPerson String? @map(\"contact_person\")\n  phoneNumber   String? @map(\"phone_number\")\n  address       String? @map(\"address\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  drugMaps      FacilityDrugMap[]\n  reports       InventoryReport[]\n  keHoachLCNTs  KeHoachLCNT[]\n  notifications Notification[]\n  activityLogs  ActivityLog[]\n\n  @@map(\"users\")\n}\n\nenum Role {\n  ADMIN\n  FACILITY\n}\n\n// MasterDrugs: Danh mục dùng chung\nmodel MasterDrug {\n  id         String  @id @default(cuid())\n  maChung    String  @unique @map(\"ma_chung\")\n  maBhyt     String? @map(\"ma_bhyt\")\n  tenThuoc   String  @map(\"ten_thuoc\")\n  hoatChat   String? @map(\"hoat_chat\")\n  hamLuong   String? @map(\"ham_luong\")\n  dangBaoChe String? @map(\"dang_bao_che\")\n  soDangKy   String? @map(\"so_dang_ky\")\n  quyCach    String? @map(\"quy_cach\")\n  donViTinh  String? @map(\"don_vi_tinh\")\n\n  tieuChuan String? @map(\"tieu_chuan\")\n  tuoiTho   String? @map(\"tuoi_tho\")\n  duongDung String? @map(\"duong_dung\")\n  nguonGoc  String? @map(\"nguon_goc\")\n\n  congTySanXuat String? @map(\"cong_ty_san_xuat\")\n  nuocSanXuat   String? @map(\"nuoc_san_xuat\")\n  diaChiSanXuat String? @map(\"dia_chi_san_xuat\")\n\n  congTyDangKy String? @map(\"cong_ty_dang_ky\")\n  nuocDangKy   String? @map(\"nuoc_dang_ky\")\n  diaChiDangKy String? @map(\"dia_chi_dang_ky\")\n\n  nhomThuoc       String? @map(\"nhom_thuoc\")\n  isKeDon         String? @map(\"is_ke_don\")\n  kiemSoatDacBiet String? @map(\"kiem_soat_dac_biet\")\n  isTrongNuoc     String? @map(\"is_trong_nuoc\")\n\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  drugMaps FacilityDrugMap[]\n\n  @@map(\"master_drugs\")\n}\n\n// FacilityDrugMap: Ánh xạ thuốc cơ sở -> danh mục chung\nmodel FacilityDrugMap {\n  id         String @id @default(cuid())\n  facilityId String @map(\"facility_id\")\n  facility   User   @relation(fields: [facilityId], references: [id], onDelete: Cascade)\n\n  maNoiBo        String  @map(\"ma_noi_bo\")\n  tenThuocNoiBo  String  @map(\"ten_thuoc_noi_bo\")\n  hoatChatNoiBo  String? @map(\"hoat_chat_noi_bo\")\n  soDangKyNoiBo  String? @map(\"so_dang_ky_noi_bo\")\n  donViTinhNoiBo String? @map(\"don_vi_tinh_noi_bo\")\n\n  masterDrugId String?     @map(\"master_drug_id\")\n  masterDrug   MasterDrug? @relation(fields: [masterDrugId], references: [id])\n\n  status         MappingStatus @default(PENDING_MAPPING)\n  adminNote      String?       @map(\"admin_note\")\n  isOutOfCatalog Boolean       @default(false) @map(\"is_out_of_catalog\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  reports InventoryReport[]\n\n  @@unique([facilityId, maNoiBo])\n  @@map(\"facility_drug_maps\")\n}\n\nenum MappingStatus {\n  PENDING_MAPPING\n  AUTO_MAPPED\n  WAITING_APPROVAL\n  APPROVED\n  REJECTED\n}\n\n// InventoryReport: Báo cáo tồn kho hàng tháng\nmodel InventoryReport {\n  id         String @id @default(cuid())\n  facilityId String @map(\"facility_id\")\n  facility   User   @relation(fields: [facilityId], references: [id], onDelete: Cascade)\n\n  mapId   String          @map(\"map_id\")\n  drugMap FacilityDrugMap @relation(fields: [mapId], references: [id], onDelete: Cascade)\n\n  reportMonth      String  @map(\"report_month\") // Format: MM/YYYY\n  tonDau           Decimal @default(0) @map(\"ton_dau\")\n  nhap             Decimal @default(0)\n  xuat             Decimal @default(0)\n  tonCuoi          Decimal @default(0) @map(\"ton_cuoi\")\n  giaVat           Decimal @default(0) @map(\"gia_vat\")\n  thanhTienTonCuoi Decimal @default(0) @map(\"thanh_tien_ton_cuoi\") // Thành tiền tồn cuối\n\n  // Additional report fields\n  soQdTrungThau String? @map(\"so_qd_trung_thau\") // Số QĐ trúng thầu (nếu có)\n  tenCongTy     String? @map(\"ten_cong_ty\") // Tên Công ty\n  ngayBatDauHd  String? @map(\"ngay_bat_dau_hd\") // Ngày bắt đầu HĐ (format: 20260101)\n  ngayKetThucHd String? @map(\"ngay_ket_thuc_hd\") // Ngày kết thúc HĐ (format: 20260101)\n  bhyt          String? @map(\"bhyt\") // BHYT (Có/Không)\n  dichVu        String? @map(\"dich_vu\") // Dịch vụ (Có/Không)\n\n  status    ReportStatus @default(PENDING) @map(\"status\")\n  adminNote String?      @map(\"admin_note\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@unique([facilityId, mapId, reportMonth])\n  @@map(\"inventory_reports\")\n}\n\nenum ReportStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n// ReportReviewLog: Lịch sử duyệt báo cáo\nmodel ReportReviewLog {\n  id          String       @id @default(cuid())\n  facilityId  String       @map(\"facility_id\")\n  reportMonth String       @map(\"report_month\") // Format: MM/YYYY\n  status      ReportStatus\n  adminNote   String?      @map(\"admin_note\")\n  adminId     String       @map(\"admin_id\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@index([facilityId, reportMonth])\n  @@index([adminId])\n  @@map(\"report_review_logs\")\n}\n\n// ReportPeriod: Quản lý tháng báo cáo\nmodel ReportPeriod {\n  id           String    @id @default(cuid())\n  month        String    @unique // Format: MM/YYYY\n  isActive     Boolean   @default(true) @map(\"is_active\")\n  year         Int\n  periodMonth  Int       @map(\"period_month\") // to easily sort\n  deadline     DateTime? @map(\"deadline\") // Hạn nộp báo cáo\n  reminderSent Boolean   @default(false) @map(\"reminder_sent\") // Đã gửi nhắc nhở chưa\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"report_periods\")\n}\n\n// KeHoachLCNT: Kế hoạch lựa chọn nhà thầu\nmodel KeHoachLCNT {\n  id         String @id @default(cuid())\n  facilityId String @map(\"facility_id\")\n  facility   User   @relation(fields: [facilityId], references: [id], onDelete: Cascade)\n\n  quyTrinh       Int       @map(\"quy_trinh\") // 1 = Luật Đấu thầu, 2 = Tự quyết định\n  loaiMuaSam     String?   @map(\"loai_mua_sam\") // \"Thuốc\" / \"Hóa chất, vật tư, thiết bị y tế\" (for quyTrinh=1)\n  maKHLCNT       String?   @map(\"ma_khlcnt\")\n  tenKHLCNT      String?   @map(\"ten_khlcnt\")\n  soQuyetDinh    String?   @map(\"so_quyet_dinh\")\n  ngayPheDuyet   DateTime? @map(\"ngay_phe_duyet\")\n  soLuongGoiThau Int?      @map(\"so_luong_goi_thau\")\n  trangThai      String?   @map(\"trang_thai\") // \"Chưa đăng tải\" / \"Đã đăng tải\"\n\n  // Fields for quyTrinh=2 (Tự quyết định)\n  loaiMuaSamTuQuyet             String?   @map(\"loai_mua_sam_tu_quyet\") // \"Thuốc\" / \"Hóa chất, vật tư, thiết bị y tế\"\n  thoiGianBatDauMuaSam          DateTime? @map(\"thoi_gian_bat_dau_mua_sam\")\n  thoiGianBatDauThucHienHopDong DateTime? @map(\"thoi_gian_bat_dau_thuc_hien_hop_dong\")\n  thoiGianThucHienHopDong       String?   @map(\"thoi_gian_thuc_hien_hop_dong\")\n  thoiGianKetThucHopDong        DateTime? @map(\"thoi_gian_ket_thuc_hop_dong\")\n\n  goiThaus  GoiThau[]\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n\n  @@map(\"ke_hoach_lcnt\")\n}\n\n// GoiThau: Gói thầu\nmodel GoiThau {\n  id        String      @id @default(cuid())\n  keHoachId String      @map(\"ke_hoach_id\")\n  keHoach   KeHoachLCNT @relation(fields: [keHoachId], references: [id], onDelete: Cascade)\n\n  tenGoiThau       String    @map(\"ten_goi_thau\")\n  giaGoiThau       Decimal?  @map(\"gia_goi_thau\")\n  linhVuc          String?   @map(\"linh_vuc\") // JSON array\n  hinhThucLCNT     String?   @map(\"hinh_thuc_lcnt\")\n  phuongThucLCNT   String?   @map(\"phuong_thuc_lcnt\")\n  loaiHopDong      String?   @map(\"loai_hop_dong\") // JSON array\n  phanLoaiGoiThau  String?   @map(\"phan_loai_goi_thau\")\n  chiTietNguonVon  String?   @map(\"chi_tiet_nguon_von\")\n  soLuongPhanLo    Int?      @map(\"so_luong_phan_lo\")\n  thoiGianToChuc   String?   @map(\"thoi_gian_to_chuc\")\n  thoiGianBatDau   DateTime? @map(\"thoi_gian_bat_dau\")\n  thoiGianThucHien String?   @map(\"thoi_gian_thuc_hien\")\n  trangThai        String?   @default(\"Chưa hoàn thành\") @map(\"trang_thai\")\n  maThongBao       String?   @map(\"ma_thong_bao\")\n\n  phanLos          PhanLoGoiThau[]\n  thongBaoMoiThaus ThongBaoMoiThau[]\n  ketQuaLCNTs      KetQuaLCNT[]\n  createdAt        DateTime          @default(now()) @map(\"created_at\")\n  updatedAt        DateTime          @updatedAt @map(\"updated_at\")\n\n  @@map(\"goi_thau\")\n}\n\n// ThongBaoMoiThau: Thông báo mời thầu\nmodel ThongBaoMoiThau {\n  id        String  @id @default(cuid())\n  goiThauId String  @map(\"goi_thau_id\")\n  goiThau   GoiThau @relation(fields: [goiThauId], references: [id], onDelete: Cascade)\n\n  maTBMT           String   @map(\"ma_tbmt\") // Mã TBMT\n  ngayDangTai      DateTime @map(\"ngay_dang_tai\") // Ngày đăng tải TBMT\n  soQdPheDuyetHSMT String   @map(\"so_qd_phe_duyet_hsmt\") // Số QĐ phê duyệt HSMT\n  ngayPheDuyetHSMT DateTime @map(\"ngay_phe_duyet_hsmt\") // Ngày phê duyệt HSMT\n  ngayDongThau     DateTime @map(\"ngay_dong_thau\") // Ngày đóng thầu\n\n  ketQuaLCNTs KetQuaLCNT[]\n  createdAt   DateTime     @default(now()) @map(\"created_at\")\n  updatedAt   DateTime     @updatedAt @map(\"updated_at\")\n\n  @@map(\"thong_bao_moi_thau\")\n}\n\n// PhanLoGoiThau: Phần lô của gói thầu\nmodel PhanLoGoiThau {\n  id        String  @id @default(cuid())\n  goiThauId String  @map(\"goi_thau_id\")\n  goiThau   GoiThau @relation(fields: [goiThauId], references: [id], onDelete: Cascade)\n\n  stt               Int\n  tenPhanLo         String   @map(\"ten_phan_lo\")\n  donViTinh         String?  @map(\"don_vi_tinh\")\n  soLuong           Decimal? @map(\"so_luong\")\n  donGia            Decimal? @map(\"don_gia\")\n  thanhTien         Decimal? @map(\"thanh_tien\")\n  thoiGianThucHien  String?  @map(\"thoi_gian_thuc_hien\")\n  donViTinhThoiGian String?  @map(\"don_vi_tinh_thoi_gian\")\n\n  ketQuaPhanLos KetQuaPhanLo[]\n  createdAt     DateTime       @default(now()) @map(\"created_at\")\n  updatedAt     DateTime       @updatedAt @map(\"updated_at\")\n\n  @@map(\"phan_lo_goi_thau\")\n}\n\n// KetQuaLCNT: Kết quả lựa chọn nhà thầu\nmodel KetQuaLCNT {\n  id        String  @id @default(cuid())\n  goiThauId String  @map(\"goi_thau_id\")\n  goiThau   GoiThau @relation(fields: [goiThauId], references: [id], onDelete: Cascade)\n\n  thongBaoMoiThauId String          @map(\"thong_bao_moi_thau_id\")\n  thongBaoMoiThau   ThongBaoMoiThau @relation(fields: [thongBaoMoiThauId], references: [id], onDelete: Cascade)\n\n  soQdPheDuyetKQLCNT  String   @map(\"so_qd_phe_duyet_kqlcnt\")\n  ngayPheDuyetKQLCNT  DateTime @map(\"ngay_phe_duyet_kqlcnt\")\n  soMatHangMoiThau    Int      @map(\"so_mat_hang_moi_thau\")\n  soMatHangTrungThau  Int      @map(\"so_mat_hang_trung_thau\")\n  tongGiaTriTrungThau Decimal  @map(\"tong_gia_tri_trung_thau\")\n\n  ketQuaPhanLos KetQuaPhanLo[]\n  createdAt     DateTime       @default(now()) @map(\"created_at\")\n  updatedAt     DateTime       @updatedAt @map(\"updated_at\")\n\n  @@map(\"ket_qua_lcnt\")\n}\n\n// KetQuaPhanLo: Kết quả từng phần lô\nmodel KetQuaPhanLo {\n  id           String     @id @default(cuid())\n  ketQuaLCNTId String     @map(\"ket_qua_lcnt_id\")\n  ketQuaLCNT   KetQuaLCNT @relation(fields: [ketQuaLCNTId], references: [id], onDelete: Cascade)\n\n  phanLoGoiThauId String        @map(\"phan_lo_goi_thau_id\")\n  phanLoGoiThau   PhanLoGoiThau @relation(fields: [phanLoGoiThauId], references: [id], onDelete: Cascade)\n\n  ketQua           String   @map(\"ket_qua\") // \"Trúng thầu\" / \"Không trúng thầu\"\n  donGiaTrungThau  Decimal? @map(\"don_gia_trung_thau\")\n  nhaThauTrungThau String?  @map(\"nha_thau_trung_thau\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"ket_qua_phan_lo\")\n}\n\n// Notification: Thông báo cho người dùng\nmodel Notification {\n  id     String @id @default(cuid())\n  userId String @map(\"user_id\")\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  type       String // MAPPING_SUBMITTED, REPORT_SUBMITTED, LCNT_CREATED, PERIOD_OPENED...\n  title      String\n  message    String\n  entityType String? @map(\"entity_type\") // \"report\", \"mapping\", \"lcnt\"...\n  entityId   String? @map(\"entity_id\")\n  entityUrl  String? @map(\"entity_url\") // Direct link to the entity\n  isRead     Boolean @default(false) @map(\"is_read\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@index([userId, isRead])\n  @@index([createdAt])\n  @@map(\"notifications\")\n}\n\n// ActivityLog: Nhật ký hoạt động\nmodel ActivityLog {\n  id     String @id @default(cuid())\n  userId String @map(\"user_id\")\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  action     String // LOGIN, CREATE, UPDATE, DELETE, APPROVE, REJECT, EXPORT\n  entityType String  @map(\"entity_type\") // \"user\", \"report\", \"mapping\", \"master_drug\", \"lcnt\"\n  entityId   String? @map(\"entity_id\")\n  details    String? // JSON string with additional details\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@index([userId])\n  @@index([createdAt])\n  @@index([entityType])\n  @@map(\"activity_logs\")\n}\n"
}

